import { useEffect, useState } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";
import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchPRData
} from "./api/githubApi";

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

function App() {
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");
  const [mode, setMode] = useState("daily");

  const [labels, setLabels] = useState([]);
  const [counts, setCounts] = useState([]);
  const [total, setTotal] = useState(0);

  // ✅ AUTO LOAD USER + REPOS AFTER LOGIN
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    fetchLoggedUser().then(res => {
      setOwner(res.data);
    });

    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) {
        setSelectedRepo(res.data[0].name);
      }
    });
  }, []);

  // ✅ TODAY FETCH
  const fetchToday = async () => {
    const today = new Date().toISOString().slice(0, 10);

    const payload = {
      repository: selectedRepo,
      startDate: today,
      endDate: today,
      mode: "daily"
    };

    const res = await fetchPRData(payload,mode);
    setLabels(res.data.labels);
    setCounts(res.data.counts);
    setTotal(res.data.total);
  };

  // ✅ NORMAL FETCH
  const fetchData = async () => {
    const today = new Date().toISOString().slice(0, 10);

    const payload = {
      repository: selectedRepo,
      startDate: today,
      endDate: today,
      mode
    };

    const res = await fetchPRData(payload,mode);
    setLabels(res.data.labels);
    setCounts(res.data.counts);
    setTotal(res.data.total);
  };

  const data = {
    labels,
    datasets: [
      {
        label: "Pull Requests",
        data: counts,
        backgroundColor: "#4F46E5"
      }
    ]
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>GitHub Analytics Dashboard</h1>

      {/* ✅ LOGIN BUTTON */}
      {!owner && (
        <button
          onClick={() =>
            (window.location.href = "http://localhost:8080/auth/github")
          }
          style={styles.loginBtn}
        >
          Login with GitHub
        </button>
      )}

      {/* ✅ SHOW USER AFTER LOGIN */}
      {owner && <h3>Logged in as: {owner}</h3>}

      {/* ✅ ONLY 3 INPUTS NOW */}
      {owner && (
        <div style={styles.form}>
          {/* ✅ REPO DROPDOWN */}
          <select
            value={selectedRepo}
            onChange={e => setSelectedRepo(e.target.value)}
          >
            {repos.map(repo => (
              <option key={repo.id} value={repo.name}>
                {repo.name}
              </option>
            ))}
          </select>

          <select onChange={e => setMode(e.target.value)}>
            <option value="daily">Daily</option>
            <option value="monthly">Monthly</option>
            <option value="yearly">Yearly</option>
          </select>

          <button onClick={fetchData}>Analyze</button>
          <button onClick={fetchToday}>Today</button>
        </div>
      )}

      {total > 0 && (
        <>
          <h2>Total PRs: {total}</h2>
          <div style={{ width: "90%", maxWidth: 950 }}>
            <Bar data={data} />
          </div>
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    textAlign: "center",
    padding: 30,
    fontFamily: "Arial",
    background: "#F8FAFC",
    minHeight: "100vh"
  },
  heading: {
    color: "#1E293B"
  },
  form: {
    display: "flex",
    gap: 10,
    justifyContent: "center",
    marginBottom: 30,
    flexWrap: "wrap"
  },
  loginBtn: {
    padding: "10px 20px",
    borderRadius: 6,
    border: "none",
    background: "#111827",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
    marginBottom: 20
  }
};

export default App;
